create table if not exists public.business_data (user_id uuid primary key references auth.users(id) on delete cascade, data jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());alter table public.business_data enable row level security;drop policy if exists "Users can read their own business data" on public.business_data;create policy "Users can read their own business data" on public.business_data for select using (auth.uid()=user_id);drop policy if exists "Users can insert their own business data" on public.business_data;create policy "Users can insert their own business data" on public.business_data for insert with check (auth.uid()=user_id);drop policy if exists "Users can update their own business data" on public.business_data;create policy "Users can update their own business data" on public.business_data for update using (auth.uid()=user_id) with check (auth.uid()=user_id);